# Implement the rule: extend the solid 2 rectangle outward in each of its four directions;
# colored points on a side block extension only on their aligned row/column.
program = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    top = min(r for r, c in cells)
    bottom = max(r for r, c in cells)
    left = min(c for r, c in cells)
    right = max(c for r, c in cells)
    out = [row[:] for row in grid]

    for r in range(top, bottom + 1):
        if not any(grid[r][c] not in (0, 2) for c in range(left)):
            for c in range(left):
                out[r][c] = 2
        if not any(grid[r][c] not in (0, 2) for c in range(right + 1, w)):
            for c in range(right + 1, w):
                out[r][c] = 2

    for c in range(left, right + 1):
        if not any(grid[r][c] not in (0, 2) for r in range(top)):
            for r in range(top):
                out[r][c] = 2
        if not any(grid[r][c] not in (0, 2) for r in range(bottom + 1, h)):
            for r in range(bottom + 1, h):
                out[r][c] = 2
    return out
'''
exec(program)
